const { isNew } = ArasModules.item;
const { itemTypeName, itemId, getState } = options;
const { activePaneId } = getState();
const hidden = isNew(itemTypeName, itemId) || !activePaneId;
if (hidden) {
	return { hidden };
}

const isDashboardEditorMode = activePaneId === 'dashboard-editor';
const labelResourceKey = isDashboardEditorMode
	? 'dashboard.dashboard_settings'
	: 'dashboard.view_dashboard';
const label = aras.getResource('', labelResourceKey);
const image = '../images/' + (isDashboardEditorMode ? 'Parameters.svg' : 'Dashboard_2.svg');

return {
	hidden: false,
	image,
	label
};
